@dataclass
class SolrUpdateState:
    """An aggregated, pending Solr update."""

    keys: list[str] = field(default_factory=list)
    adds: list[SolrDocument] = field(default_factory=list)
    deletes: list[str] = field(default_factory=list)
    commit: bool = False

    def __add__(self, other: 'SolrUpdateState') -> 'SolrUpdateState':
        return SolrUpdateState(
            keys=self.keys + other.keys,
            adds=self.adds + other.adds,
            deletes=self.deletes + other.deletes,
            commit=self.commit or other.commit,
        )

    def has_changes(self) -> bool:
        return bool(self.adds or self.deletes)

    def to_solr_requests_json(self, indent: str | None = None, sep: str = ',') -> str:
        result = '{'
        if self.deletes:
            result += f'"delete":{json.dumps(self.deletes, indent=indent)}{sep}'
        for doc in self.adds:
            result += f'"add":{json.dumps({"doc": doc}, indent=indent)}{sep}'
        if self.commit:
            result += f'"commit":{{}}{sep}'
        if result.endswith(sep):
            result = result[: -len(sep)]
        return result + '}'

    def clear_requests(self) -> None:
        self.adds.clear()
        self.deletes.clear()


def _get_data_provider() -> DataProvider:
    global data_provider
    if data_provider is None:
        data_provider = get_data_provider('default')
    return data_provider


class AbstractSolrUpdater(abc.ABC):
    """Shared contract for record-specific Solr updaters."""

    key_prefix: str

    def __init__(self, data_provider: DataProvider | None = None):
        self.data_provider: DataProvider = (
            data_provider if data_provider is not None else _get_data_provider()
        )

    def key_test(self, key: str) -> bool:
        return key.startswith(self.key_prefix)

    async def preload_keys(self, keys: Iterable[str]):
        await self.data_provider.preload_documents(list(keys))

    @abc.abstractmethod
    async def update_key(self, thing: dict) -> SolrUpdateState:
        raise NotImplementedError


class EditionSolrUpdater(AbstractSolrUpdater):
    key_prefix = '/books/'

    async def update_key(self, thing: dict) -> SolrUpdateState:
        update = SolrUpdateState()
        key = thing['key']
        thing_type = thing['type']['key']

        if thing_type == '/type/redirect':
            logger.warning("Found redirect to %s", thing['location'])
            update.deletes.append(key)
            target = await self.data_provider.get_document(thing['location'])
            if not target:
                logger.warning("No document found for %r", thing['location'])
                return update
            return update + await self.update_key(target)
        elif thing_type == '/type/delete':
            update.deletes.append(key)
        elif thing_type == '/type/edition':
            if thing.get('works'):
                update.keys.append(thing['works'][0]['key'])
                # Make sure we remove any fake works created from orphaned editions
                update.deletes.append(key.replace('/books/', '/works/'))
            else:
                # index the edition as it does not belong to any work
                update.keys.append(key)
        elif thing_type == '/type/work':
            update.keys.append(key)
        else:
            logger.warning(
                "Found a document of type %r. Ignoring...", thing_type
            )
        return update


class WorkSolrUpdater(AbstractSolrUpdater):
    key_prefix = '/works/'

    async def preload_keys(self, keys: Iterable[str]):
        keys = list(keys)
        await super().preload_keys(keys)
        self.data_provider.preload_editions_of_works(
            [k for k in keys if k.startswith('/works/')]
        )

    async def update_key(self, work: dict) -> SolrUpdateState:
        update = SolrUpdateState()
        wkey = work['key']
        work_type = work['type']['key']

        # Handle edition records as well
        # When an edition does not contain a works list, create a fake work and index it.
        if work_type == '/type/edition':
            fake_work = {
                # Solr uses type-prefixed keys. It's required to be unique across
                # all types of documents. The website takes care of redirecting
                # /works/OL1M to /books/OL1M.
                'key': wkey.replace("/books/", "/works/"),
                'type': {'key': '/type/work'},
                'title': work.get('title'),
                'editions': [work],
                'authors': [
                    {'type': '/type/author_role', 'author': {'key': a['key']}}
                    for a in work.get('authors', [])
                ],
            }
            # Hack to add subjects when indexing /books/ia:xxx
            if work.get("subjects"):
                fake_work['subjects'] = work['subjects']
            return await self.update_key(fake_work)
        elif work_type == '/type/work':
            try:
                solr_doc = await build_data(work)
            except:
                logger.error("failed to update work %s", work['key'], exc_info=True)
            else:
                if solr_doc is not None:
                    iaids = solr_doc.get('ia') or []
                    # Delete all ia:foobar keys
                    if iaids:
                        update.deletes += [f"/works/ia:{iaid}" for iaid in iaids]
                    update.adds.append(solr_doc)
        elif work_type in ['/type/delete', '/type/redirect']:
            update.deletes.append(wkey)
        else:
            logger.error("unrecognized type while updating work %s", wkey)

        return update


