        if thing.get('date', None):
            d['date'] = thing['date']

        if top_work:
            d['top_work'] = top_work
        d['work_count'] = work_count
        d['top_subjects'] = top_subjects

        update = SolrUpdateState(adds=[d])
        redirect_keys = self.data_provider.find_redirects(akey)
        if redirect_keys:
            update.deletes += redirect_keys
        return update


