        update = SolrUpdateState()
        if thing['type']['key'] == self.thing_type:
            fake_key = thing['key'].replace('/books/', '/works/')
            if thing.get("works"):
                update.keys.append(thing["works"][0]['key'])
                update.deletes.append(fake_key)
            else:
                update.keys.append(fake_key)
