from openlibrary.core import db
from openlibrary.core.bookshelves import Bookshelves


class Bestbook(db.CommonExtras):
    """Best Book Awards"""

    TABLENAME = "bestbooks"
    PRIMARY_KEY = ("award_id",)
    ALLOW_DELETE_ON_CONFLICT = False

    class AwardConditionsError(Exception):
        pass

    @classmethod
    def prepare_query(cls, select="*", work_id=None, username=None, topic=None):
        conditions = []
        vars = {}
        if work_id:
            conditions.append("work_id = $work_id")
            vars["work_id"] = work_id
        if username:
            conditions.append("username = $username")
            vars["username"] = username
        if topic:
            conditions.append("topic = $topic")
            vars["topic"] = topic
        query = f"SELECT {select} FROM {cls.TABLENAME}"
        if conditions:
            query += " WHERE " + " AND ".join(conditions)
        return query, vars

    @classmethod
    def get_count(cls, work_id=None, username=None, topic=None) -> int:
        oldb = db.get_db()
        query, vars = cls.prepare_query(
            select="count(*)", work_id=work_id, username=username, topic=topic
        )
        result = oldb.query(query, vars=vars)
        return result[0]['count'] if result else 0

    @classmethod
    def get_awards(cls, work_id=None, username=None, topic=None) -> list:
        oldb = db.get_db()
        query, vars = cls.prepare_query(
            work_id=work_id, username=username, topic=topic
        )
        return list(oldb.query(query, vars=vars))

    @classmethod
    def add(cls, username, work_id, topic, comment="", edition_id=None):
        cls.check_if_award_conditions_met(username, work_id, topic)
        oldb = db.get_db()
        return oldb.insert(
            cls.TABLENAME,
            username=username,
            work_id=work_id,
            edition_id=edition_id,
            topic=topic,
            comment=comment or "",
        )

    @classmethod
    def remove(cls, username, work_id=None, topic=None) -> int:
        if not (work_id or topic):
            raise ValueError("work_id or topic is required")
        oldb = db.get_db()
        where = {'username': username, 'work_id': work_id, 'topic': topic}
        return oldb.delete(
            cls.TABLENAME,
            where="username=$username AND (work_id=$work_id OR topic=$topic)",
            vars=where,
        )

    @classmethod
    def get_leaderboard(cls) -> list[dict]:
        oldb = db.get_db()
        result = oldb.query(
            f"SELECT work_id, COUNT(*) AS count FROM {cls.TABLENAME} "
            "GROUP BY work_id ORDER BY count DESC"
        )
        return [dict(r) for r in result]

    @classmethod
    def check_if_award_conditions_met(cls, username, work_id, topic):
        errors = []
        if not Bookshelves.user_has_read_work(username=username, work_id=work_id):
            errors.append(
                "Only books which have been marked as read may be given awards"
            )
        if cls.get_awards(username=username, work_id=work_id):
            errors.append("A work may only be nominated one time for a best book award")
        for a in cls.get_awards(username=username, topic=topic) or []:
            try:
                wid = a['work_id']
            except (KeyError, TypeError):
                wid = getattr(a, 'work_id', None)
            if str(wid) != str(work_id):
                errors.append(
                    f"A topic may only be nominated one time for a best book award: "
                    f"{topic} already used"
                )
                break
        if errors:
            raise cls.AwardConditionsError(" ".join(errors))
        return True
